function checkOutLogin(){$.ajax({async:!1,url:"/AppService/setUp/checkOutLogin.xhtml",dataType:"json",type:"POST",data:{},cache:!1,error:function(){show_tips("网络繁忙，请稍后再试。")},success:function(){window.location.href="/login/login.shtml"}})}function headerInfo(){$.ajax({async:!1,url:"/AppService/setUp/headerInfo.xhtml",dataType:"json",type:"POST",data:{},cache:!1,error:function(){show_tips("网络繁忙，请稍后再试。")},success:function(n){n.returnCode=="0000"?($("#loginYes").show(),$("#loginNo").hide(),$("#userId").val(n.cmfUserId),$("#login_userinfo").html(n.name).prop("href","/AppService/applicationGroups.shtml?mainCatId=MY_ACCOUNT&thirdCatId=RICHES_INFO")):($("#loginNo").show(),$("#loginYes").hide());$("#loginYesPublic").is(":visible")&&$("#loginNo").hide()}})}function close_tips(n){$("#"+n).hide()}function show_tips3(n){$("#hint_tips_btn3").show().find("span").html(n)}function show_tips(n,t){t||(t="确认");$("#hint_tips_btn1").show().find("span").html(n);$("#hint_tips_btn1").show().find("input").val(t)}function show_tips2(n,t,i,r,u){u=u||function(){};$("#hint_tips_btn2").show().find("span").html(n);$("#tips_btn1_btn").val(t).attr("onclick","gotoUrl('"+r+"')");$("#tips_btn2_btn").val(i).attr("onclick",u+"()")}function close_tips2(){$("#hint_tips_btn2").hide()}function gotoUrl(n){window.location.href=n}function openToUrl(n){window.open(n)}$(document).ready(function(){$(".page-top-right .weixin").hover(function(){$(".weixin_img").show()},function(){$(".weixin_img").hide()});headerInfo()})